import{_ as c,l as s,o as a,c as d,v as t,p as i,x as o,d as n,i as l,S as b}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"etcd / Chubby","description":"","frontmatter":{"title":"etcd / Chubby","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/etcd-chubby.md","filePath":"cs/etcd-chubby.md","lastUpdated":1789023840000}'),h={name:"cs/etcd-chubby.md"};function u(p,e,f,_,m,C){const r=s("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="etcd-chubby" tabindex="-1">etcd / Chubby <a class="header-anchor" href="#etcd-chubby" aria-label="Permalink to &quot;etcd / Chubby&quot;">​</a></h1><div class="epigraph"><p>小容量线性一致的锁与配置服务：共识复制状态机对外变成文件、会话和通知。Kubernetes 与 GFS 客户端都把脑裂问题外包给它。</p><footer>—— 据 Burrows, The Chubby Lock Service for Loosely-Coupled Distributed Systems, OSDI 2006；etcd 基于 Raft 的工程实践整理</footer></div><p>上一课<a href="/cs/distributed-lock-fencing">fencing</a>要一个发 token 的线性一致服务。缺口是<strong>产品形态</strong>：Chubby 是 Google 的锁服务；etcd 是 Raft 键值，API 不同，规格同族。本课不重写 Raft 投票。后课 PoW 是无许可成员的另一套「谁说了算」，不要和 Chubby 混。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需要：选主、配置发布、小组缓存一致性。自己在每个应用里嵌 Paxos 容易嵌错。Chubby：类文件系统节点、advisory lock、sequencer、事件通知、会话 keepalive（<a href="/cs/leases">租约</a>）。客户端缓存节点，失效靠通知+租约，接 Gray–Cheriton。底层 Paxos（Made Live）。</p><p>etcd：<code>/key</code> 修订号、lease、watch、事务 <code>Compare</code>。修订号当 fencing token。Kubernetes 把对象存在 etcd，控制器调和是最终一致，<strong>存储</strong>是 CP。</p><p><span class="marginnote">Chubby 论文强调：锁是建议性的，正确性靠 sequencer 进 RPC。etcd 不声称自己是 Chubby 克隆，但课程序列里它们填同一缺口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>部署：五节点跨故障域，避免双机房各两台的偶数脑裂。请求走领导者。watch 是前缀广播的工程近似，不是独立 pub/sub 保证（后课）。快照与压缩修订号，接<a href="/cs/raft-membership-snapshot">Raft 快照</a>。</p>',9)),(a(),i(b,null,{default:o(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20API%5B%22%E9%94%81%20%2F%20KV%20%2F%20watch%22%5D%0A%20%20API%20--%3E%20RSM%5B%22Paxos%20%E6%88%96%20Raft%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20RSM%20--%3E%20TOK%5B%22%E4%BF%AE%E8%AE%A2%E5%8F%B7%20%2F%20sequencer%22%5D%0A%20%20TOK%20--%3E%20FENCE%5B%22%E8%B5%84%E6%BA%90%20fencing%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>不要把大型 blob 放进 etcd：RSM 日志不是对象存储。那是后课 GFS/S3。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>会话死 ⇒ 临时节点/lease 键删除 ⇒ 选主观察者收到 watch ⇒ 新主 acquire。这条链的正确性 = 租约算术 + 删除的线性一致 + fencing。任一环用最终一致缓存跳过，脑裂回来。</p><p>读：Chubby/etcd 都可以从跟随者读以降低延迟，线性一致读必须注明（etcd <code>linearizable</code> vs <code>serializable</code> 读）。默认读档要当规格读，不当营销读。</p><p>本课不把 Consul、Zookeeper 再写一遍：ZK 上一课已钉。三者都是元数据 RSM。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部 etcd API，不写 Chubby 多单元地理。后课默认：集群协调数据放 CP 的锁/KV；业务大数据放专用存储。PoW 下一课处理开放成员，不替代数据中心锁服务。</p><p>小日志、强一致、会话、通知。四个词就是这类服务。应用仍要自己把 token 打进副作用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Chubby/etcd：RSM 做成锁与配置 API。</li><li>修订号/sequencer 供 fencing；会话是租约。</li><li>不存放业务大对象；跟随者读可能掉线性一致档。</li><li>出处：Burrows, OSDI 2006；Raft；etcd 文档中的线性一致读。</li></ul>',10))])}const A=c(h,[["render",u]]);export{y as __pageData,A as default};
